function convoyCount(target: number, position: number[], speed: number[]): number {
  const n = position.length;
  let count = 0;
  for (let i = 0; i < n; i++) {
    let leads = true;
    for (let j = 0; j < n && leads; j++) {
      // time_j >= time_i  <=>  (target - p_j) * s_i >= (target - p_i) * s_j
      if (position[j] > position[i] && (target - position[j]) * speed[i] >= (target - position[i]) * speed[j]) leads = false;
    }
    if (leads) count++;
  }
  return count;
}

