function convoyCount(target: number, position: number[], speed: number[]): number {
  const order = position.map((_, i) => i).sort((a, b) => position[b] - position[a]);
  const stack: number[] = []; // arrival times of convoys, front to back
  for (const i of order) {
    const time = (target - position[i]) / speed[i];
    if (stack.length === 0 || time > stack[stack.length - 1]) stack.push(time);
  }
  return stack.length;
}

