function convoyCount(target: number, position: number[], speed: number[]): number {
  const cars = position.map((p, i) => [p, speed[i]]).sort((a, b) => b[0] - a[0]);
  let count = 0, last = -1;
  for (const [p, s] of cars) {
    const time = (target - p) / s;
    if (time > last) {
      count++;
      last = time;
    }
  }
  return count;
}

